           question: "Why do cats knead blankets?",
           answer: [
             "Kneading is a comforting behavior that starts in kittenhood when nursing.",
             "Adult cats often keep doing it when they feel safe, cozy, or affectionate."
           ]
         }
       ];

       function FAQItem({ question, answer }, index) {
         const detailsId = `faq-answer-${index}`;
